ಅಕ್ಷರ * pcTaskGetName( TaskHandle_t x_Task_ಗಮ್ಯ_Query )
{
    TCB_t * pxTCB;

    traceENTER_pcTaskGetName( x_Task_ಗಮ್ಯ_Query );

    /* If null is passed in here then the name of the calling task is being
     * queried. */
    pxTCB = prvGetTCBFromHandle( x_Task_ಗಮ್ಯ_Query );
    configASSERT( pxTCB );

    traceRETURN_pcTaskGetName( &( pxTCB->pcTaskName[ 0 ] ) );

    ಹಿಂತಿರುಗಿ &( pxTCB->pcTaskName[ 0 ] );
}
